    """ Find a palindrome string S that represents a mathematical expression evaluating to n.

    The string must satisfy:
    - Length between 1 and 1000 characters
    - Consists only of digits 1-9 and the multiplication symbol '*'
    - Is a palindrome (reads the same forwards and backwards)
    - First character must be a digit
    - When evaluated as a mathematical expression, equals n

    Args:
        n: An integer between 1 and 10^12

    Returns:
        A palindrome string representing an expression that evaluates to n,
        or '-1' if no such string exists.

    >>> find_palindrome_expression(363)
    '11*3*11'
    >>> find_palindrome_expression(101)
    '-1'
    >>> find_palindrome_expression(3)
    '3'
    """
    MAX_LEN = 1000

    def is_pal(s: str) -> bool:
        return s == s[::-1]

    def ok_expr(s: str) -> bool:
        if not (1 <= len(s) <= MAX_LEN):
            return False
        if not is_pal(s):
            return False
        if not s[0].isdigit():
            return False
        for c in s:
            if c not in '123456789*':
                return False
        try:
            return eval(s) == n
        except Exception:
            return False

    if n is None or n < 1 or n > 10**12:
        return '-1'

    sn = str(n)
    # Trivial: n itself is a palindrome (single-digit n -> str(n)).
    if is_pal(sn):
        return sn

    def factorize(x: int):
        fac = {}
        d = 2
        while d * d <= x:
            while x % d == 0:
                fac[d] = fac.get(d, 0) + 1
                x //= d
            d += 1 if d == 2 else 2
        if x > 1:
            fac[x] = fac.get(x, 0) + 1
        return fac

    fac = factorize(n)
    divisors = [1]
    for p, e in fac.items():
        new = []
        pw = 1
        for _ in range(e + 1):
            for dv in divisors:
                new.append(dv * pw)
            pw *= p
        divisors = new
