        if len(sa) > MAX_LEN // 2 - 1:
            continue
        b = n // (a * int(sa[::-1]))
        sb = str(b)
        if len(sb) > MAX_LEN - 2 * len(sa) - 2:
            continue
        if b == 1 or is_pal(sb):
            s = sa + '*' + sb + '*' + sa
